#include <bits/stdc++.h>
using namespace std;
int main(){
    int n; scanf("%d",&n);
    vector<vector<int>> a(n, vector<int>(n,0));
    for(int i=0;i<n-1;i++){int x,y; scanf("%d %d",&x,&y); a[x-1][y-1]=1;}
    vector<int> rowC(n,0), colC(n,0), inR(n,1), inC(n,1), rowAt(n), colAt(n);
    for(int r=0;r<n;r++) for(int c=0;c<n;c++) if(a[r][c]){rowC[r]++; colC[c]++;}
    for(int k=n-1;k>=0;k--){
        int c=-1; for(int j=0;j<n;j++) if(inC[j] && colC[j]==0){c=j;break;}
        int r=-1; for(int i=0;i<n;i++) if(inR[i] && (r<0 || rowC[i]>rowC[r])) r=i;
        rowAt[k]=r; colAt[k]=c; inR[r]=0; inC[c]=0;
        for(int j=0;j<n;j++) if(inC[j]) colC[j]-=a[r][j];
        for(int i=0;i<n;i++) if(inR[i]) rowC[i]-=a[i][c];
    }
    vector<array<int,3>> ops;
    vector<int> curR(n), curC(n);
    iota(curR.begin(),curR.end(),0); iota(curC.begin(),curC.end(),0);
    for(int k=0;k<n;k++){
        int p=find(curR.begin(),curR.end(),rowAt[k])-curR.begin();
        if(p!=k){ swap(curR[p],curR[k]); ops.push_back({1,p+1,k+1}); }
    }
    for(int k=0;k<n;k++){
        int p=find(curC.begin(),curC.end(),colAt[k])-curC.begin();
        if(p!=k){ swap(curC[p],curC[k]); ops.push_back({2,p+1,k+1}); }
    }
    printf("%d\n",(int)ops.size());
    for(auto&o:ops) printf("%d %d %d\n",o[0],o[1],o[2]);
}

