using namespace std;
vector<vector<int>> g; vector<int> sz, lvl; vector<char> done;
int calc(int u,int p){ sz[u]=1; for(int v:g[u]) if(v!=p && !done[v]) sz[u]+=calc(v,u); return sz[u]; }
int findC(int u,int p,int tot){ for(int v:g[u]) if(v!=p && !done[v] && 2*sz[v]>tot) return findC(v,u,tot); return u; }
bool dec(int u,int d){
    int c=findC(u,-1,calc(u,-1));
    if(d>=26) return false;
    lvl[c]=d; done[c]=1;
    for(int v:g[c]) if(!done[v] && !dec(v,d+1)) return false;
    return true;
}
int main(){
