    if(!dec(0,0)){ puts("Impossible!"); return 0; }
    for(int i=0;i<n;i++) printf("%c%c",'A'+lvl[i], i+1<n?' ':'\n');
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    long long n; scanf("%lld",&n);
    long long c[5]={0,0,0,0,0}, S=0;
    for(int i=0;i<n;i++){int a; scanf("%d",&a); c[a]++; S+=a;}
    vector<pair<int,long long>> A;
    for(int v=4;v>=0;v--) if(c[v]) A.push_back({v,c[v]});
    long long best=-1;
    for(long long x=0;4*x<=S;x++){
        if((S-4*x)%3) continue;
        long long y=(S-4*x)/3;
        if(x+y>n) continue;
        vector<pair<int,long long>> T;
        if(x) T.push_back({4,x});
        if(y) T.push_back({3,y});
        if(n-x-y) T.push_back({0,n-x-y});
        long long cost=0; size_t i=0,j=0;
        long long ra=A[0].second, rt=T[0].second;
        while(i<A.size() && j<T.size()){
            long long m=min(ra,rt);
            cost+=llabs((long long)A[i].first-T[j].first)*m;
            ra-=m; rt-=m;
            if(!ra && ++i<A.size()) ra=A[i].second;
            if(!rt && ++j<T.size()) rt=T[j].second;
        }
        cost/=2;
        if(best<0||cost<best) best=cost;
    }
    printf("%lld\n",best);
}

#include <bits/stdc++.h>
