int par[100005];
int f(int x){ return par[x]==x?x:par[x]=f(par[x]); }
int main(){
    int n,m,p,q; scanf("%d %d %d %d",&n,&m,&p,&q);
    vector<int> X(m),Y(m); vector<long long> Lh(m);
    for(int i=1;i<=n;i++) par[i]=i;
    for(int i=0;i<m;i++){ scanf("%d %d %lld",&X[i],&Y[i],&Lh[i]); par[f(X[i])]=f(Y[i]); }
    vector<long long> tot(n+1,0);
    for(int i=0;i<m;i++) tot[f(X[i])]+=Lh[i];
    int c=0;
    priority_queue<pair<long long,int>,vector<pair<long long,int>>,greater<>> pq;
    for(int i=1;i<=n;i++) if(f(i)==i){ c++; pq.push({tot[i],i}); }
    if(q>c || p<c-q){ puts("NO"); return 0; }
    vector<pair<int,int>> out;
    while((int)pq.size()>q){
        auto [t1,r1]=pq.top(); pq.pop();
        auto [t2,r2]=pq.top(); pq.pop();
        long long L=min(1000000000LL, t1+t2+1);
        out.push_back({r1,r2});
        par[f(r2)]=f(r1);
        pq.push({t1+t2+L, r1});
    }
    int extra=p-(c-q);
    if(extra>0){
        vector<int> first(n+1,-1); int u=-1,v=-1;
        for(int i=1;i<=n && u<0;i++){ int r=f(i); if(first[r]<0) first[r]=i; else { u=first[r]; v=i; } }
        if(u<0){ puts("NO"); return 0; }
        for(int k=0;k<extra;k++) out.push_back({u,v});
    }
    puts("YES");
    for(auto [a,b]:out) printf("%d %d\n",a,b);
}

