int main(){
    scanf("%d %d",&n,&m);
    vector<string> g(n); static char buf[2105];
    for(auto&s:g){ scanf("%s",buf); s=buf; }
    P.assign(n+1, vector<int>(m+1,0));
    int W=0, minr=1e9,maxr=-1,minc=1e9,maxc=-1;
    for(int i=0;i<n;i++) for(int j=0;j<m;j++){
        int w=g[i][j]=='w';
        P[i+1][j+1]=P[i][j+1]+P[i+1][j]-P[i][j]+w;
        if(w){ W++; minr=min(minr,i); maxr=max(maxr,i); minc=min(minc,j); maxc=max(maxc,j); }
    }
    int D0=max(maxr-minr,maxc-minc)+1;
    for(int d=D0; d<=min(n,m); d++)
        for(int r0=max(0,maxr-d+1); r0<=min(minr,n-d); r0++)
            for(int c0=max(0,maxc-d+1); c0<=min(minc,m-d); c0++){
                int cnt = (d==1) ? R(r0,c0,r0,c0)
                    : R(r0,c0,r0,c0+d-1)+R(r0+d-1,c0,r0+d-1,c0+d-1)+R(r0+1,c0,r0+d-2,c0)+R(r0+1,c0+d-1,r0+d-2,c0+d-1);
                if(cnt!=W) continue;
                for(int k=0;k<d;k++){
                    int pts[4][2]={{r0,c0+k},{r0+d-1,c0+k},{r0+k,c0},{r0+k,c0+d-1}};
                    for(auto&pt:pts) if(g[pt[0]][pt[1]]=='.') g[pt[0]][pt[1]]='+';
                }
                for(auto&s:g) puts(s.c_str());
                return 0;
            }
    puts("-1");
}

