#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const ll MOD=1000000009LL;
map<pair<ll,ll>,int> pos;
vector<ll> X,Y;
int supp(ll x,ll y){ int c=0; for(ll d=-1;d<=1;d++) c+=pos.count({x+d,y-1}); return c; }
bool removable(int c){
    for(ll d=-1;d<=1;d++){
        auto it=pos.find({X[c]+d,Y[c]+1});
        if(it!=pos.end() && supp(X[c]+d,Y[c]+1)==1) return false;
    }
    return true;
}
int main(){
    int m; scanf("%d",&m);
    X.resize(m); Y.resize(m);
    for(int i=0;i<m;i++){ scanf("%lld %lld",&X[i],&Y[i]); pos[{X[i],Y[i]}]=i; }
    set<int> rem;
    for(int i=0;i<m;i++) if(removable(i)) rem.insert(i);
    ll ans=0;
    for(int step=0;step<m;step++){
        int c = (step%2==0) ? *rem.rbegin() : *rem.begin();
        rem.erase(c);
        ans=(ans*m+c)%MOD;
        ll cx=X[c], cy=Y[c];
        pos.erase({cx,cy});
        for(ll x=cx-2;x<=cx+2;x++) for(ll y=cy-1;y<=cy;y++){
            auto it=pos.find({x,y});
            if(it==pos.end()) continue;
            if(removable(it->second)) rem.insert(it->second); else rem.erase(it->second);
        }
    }
    printf("%lld\n",ans);
}

