#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
vector<int> mx, lz;
void upd(int o,int l,int r,int ql,int qr){
    if(qr<l||r<ql) return;
    if(ql<=l&&r<=qr){ mx[o]++; lz[o]++; return; }
    int m=(l+r)/2; upd(2*o,l,m,ql,qr); upd(2*o+1,m+1,r,ql,qr); mx[o]=max(mx[2*o],mx[2*o+1])+lz[o];
}
int qry(int o,int l,int r,int ql,int qr){
    if(qr<l||r<ql) return -1000000000;
    if(ql<=l&&r<=qr) return mx[o];
    int m=(l+r)/2; return max(qry(2*o,l,m,ql,qr),qry(2*o+1,m+1,r,ql,qr))+lz[o];
}
int main(){
    int n,a; scanf("%d %d",&n,&a);
    vector<ll> L(n),R(n),co;
    for(int i=0;i<n;i++){ ll x,d; scanf("%lld %lld",&x,&d); L[i]=x; R[i]=x+d; co.push_back(x); co.push_back(x+d); }
    sort(co.begin(),co.end()); co.erase(unique(co.begin(),co.end()),co.end());
    int M=co.size()-1;
    vector<int> SL(n),SR(n),ord(n);
    for(int i=0;i<n;i++){
        SL[i]=lower_bound(co.begin(),co.end(),L[i])-co.begin();
        SR[i]=lower_bound(co.begin(),co.end(),R[i])-co.begin()-1; ord[i]=i;
    }
    sort(ord.begin(),ord.end(),[&](int x,int y){return R[x]<R[y];});
    auto pick=[&](int k, vector<int>* out){
        mx.assign(4*M,0); lz.assign(4*M,0); int cnt=0;
        for(int i:ord) if(qry(1,0,M-1,SL[i],SR[i])+1<=k){ upd(1,0,M-1,SL[i],SR[i]); cnt++; if(out) out->push_back(i+1); }
        return cnt;
    };
    int lo=1, hi=n;
    while(lo<hi){ int mid=(lo+hi)/2; if(pick(mid,nullptr)>=a) hi=mid; else lo=mid+1; }
    vector<int> ch; pick(lo,&ch);
    printf("%d\n",lo);
    for(int i=0;i<a;i++) printf("%d ",ch[i]);
    puts("");
}

