            if(i<vec.size() && vec[i]>0) bonus=max(bonus,(long long)vec[i]);
        } else if(s<r && g.count(r)){
            vector<int>& w=g[r];
            for(size_t i=0;i<min(vec.size(),w.size());i++){
                if(vec[i]+w[i]>0) total+=vec[i]+w[i]; else break;
            }
        }
    }
    printf("%lld\n",total+bonus);
}

