#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
vector<ll> mn, lz;
void add(int o,int l,int r,int ql,int qr,ll v){
    if(qr<l||r<ql) return;
    if(ql<=l&&r<=qr){ mn[o]+=v; lz[o]+=v; return; }
    int m=(l+r)/2; add(2*o,l,m,ql,qr,v); add(2*o+1,m+1,r,ql,qr,v); mn[o]=min(mn[2*o],mn[2*o+1])+lz[o];
}
ll qmin(int o,int l,int r,int ql,int qr){
    if(qr<l||r<ql) return LLONG_MAX/4;
    if(ql<=l&&r<=qr) return mn[o];
    int m=(l+r)/2; return min(qmin(2*o,l,m,ql,qr),qmin(2*o+1,m+1,r,ql,qr))+lz[o];
}
void build(int o,int l,int r,const vector<ll>& s){
    lz[o]=0;
    if(l==r){ mn[o]=s[l]; return; }
    int m=(l+r)/2; build(2*o,l,m,s); build(2*o+1,m+1,r,s); mn[o]=min(mn[2*o],mn[2*o+1]);
}
int main(){
    int n,m; ll k; scanf("%d %d %lld",&n,&m,&k);
    vector<ll> f(n), s(m), D;
    for(auto&x:f) scanf("%lld",&x); for(auto&x:s) scanf("%lld",&x);
    D=f; D.insert(D.end(),s.begin(),s.end());
    sort(D.begin(),D.end()); D.erase(unique(D.begin(),D.end()),D.end());
    int M=D.size();
    vector<ll> cntF(M,0), sl(M); ll run=0;
    for(ll x:f) cntF[lower_bound(D.begin(),D.end(),x)-D.begin()]++;
    for(int j=0;j<M;j++){ run+=cntF[j]; sl[j]=k*(D[j]+1)-run; }
    mn.assign(4*M,0); lz.assign(4*M,0); build(1,0,M-1,sl);
    if(qmin(1,0,M-1,0,M-1)<0){ puts("-1"); return 0; }
    vector<int> ch;
    for(int i=0;i<m;i++){
        int j0=lower_bound(D.begin(),D.end(),s[i])-D.begin();
        if(qmin(1,0,M-1,j0,M-1)>=1){ add(1,0,M-1,j0,M-1,-1); ch.push_back(i+1); }
    }
    printf("%d\n",(int)ch.size());
    for(int x:ch) printf("%d ",x);
    puts("");
}
